// Games, wired to the engine: the one file of this module that holds
// `$` and the mod's state (the engine follows `$` and atoms only within the
// file whose hook received them), handing the rest closures. /drip lists the
// games and starts one in the shared native overlay (../overlay), over
// Claude's window or the whole screen as the /config row `display` says; the
// overlay takes the pointer and keys while a game is on. Each game posts its
// score as it goes, and the top one is kept for the next round to beat.
// /drip (or /drip list) opens the Drip pane: every game and drip, here or in the
// gallery, each with who made it and Play (Install for the gallery's). Every
// game and drip is free.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On, PluginOptions } from 'claude-code'

import { ancestorsOf, eventsOf, overlayHost, prepareOverlay, type OverlayDeps, type Placement, type Prepared } from '../overlay/host.ts'
import { selectTarget, type Target, type TerminalEnv } from '../overlay/target.ts'
import { BUILTIN_EFFECT_LIST, ONE_SHOT_EFFECTS } from '../drips/effects.ts'
import { dripsDir, gamesDir, loadDrips, loadGames, skippedText, type FolderDeps, type FolderGame } from '../content/folders.ts'
import { GALLERY_API, get as galleryGet, listing as galleryListing, type Entry } from '../content/gallery.ts'
import { COVER_FILES, DRIP_AUTHOR, NAME } from '../content/rules.js'
import { share as galleryShare } from '../content/share.ts'
import { readCustoms } from '../drips/library.ts'
import { GAMES, gameDoc, gameOf } from './games/index.ts'
import type { Game } from './games/game.ts'
import { LOGO_ALT, LOGO_RATIO, logoSvg } from './brand.ts'
import { BUILT_IN, TYPES, emojiOf, type Kind } from './catalog.ts'
import { FAVOURITES_KEY } from './favourites.ts'
import { scoresOf, type Store } from './scores.ts'
import { settingsOf, type Settings } from './settings.ts'

/** A drip the pane asked to play: the drips' half (../drips) takes it. */
const queued = atom({ plugin: 'drip', key: 'queued' } as const, null as { recipe: string; at: number } | null)
/** The pane's search, type filter and page (from 0). */
const query = atom({ plugin: 'drip', key: 'query' } as const, '')
const filter = atom({ plugin: 'drip', key: 'filter' } as const, 'all' as Kind | 'all')
const page = atom({ plugin: 'drip', key: 'page' } as const, 0)
/** Bumped when a screenshot the pane waits for has loaded: the page redraws with it. */
const shotTick = atom({ plugin: 'drip', key: 'shotTick' } as const, 0)
/** The item the pane shows on its own page ("game:snake"); none, the table. */
const detail = atom({ plugin: 'drip', key: 'detail' } as const, null as string | null)
/** The starred items ("game:missiles"), the tray's buttons: kept in the store across sessions (../drips loads them). */
const favourites = atom({ plugin: 'drip', key: 'favourites' } as const, [] as string[])
/** The tray's row is open (the drip button by the prompt). */
const bandOpen = atom({ plugin: 'drip', key: 'bandOpen' } as const, false)

/** The pane's logo: it follows the app's own light or dark, as the app's buttons do. */
const LOGO = logoSvg('auto')

/** The Drip pane: /drip (or /drip list) opens it. */
export const PANE = 'drip'
/** What /drip says in the conversation once the pane is open. */
export const OPENED = 'Drip is open in the side panel.'
/** How long what the gallery has is kept before it's asked again, in ms. */
const GALLERY_MS = 5 * 60_000
/** The gallery's listing as last read, for the pane's draws. */
let galleryKept: { at: number; index: Awaited<ReturnType<typeof galleryListing>> } | null = null

/** A drip's name as the card shows it: "matrix" → "Matrix". */
const titleOf = (name: string) => name.charAt(0).toUpperCase() + name.slice(1)

/** Every built-in game's names, which the person's own games may not take. */
const TAKEN = new Set(GAMES.flatMap(g => [g.name, ...(g.aliases ?? [])]))

let settings: Settings
/** This load's pieces: the overlay's binary, built on first use, and the window Claude runs in. */
let native: Promise<Prepared> | null = null
/** The title of the game on screen, if one is: only one plays at a time. */
let gameOpen: string | null = null
let target: Promise<Target | null> | null = null
/** Said once per load: Claude's window not found. */
let isMissedSaid = false

const short = (err: unknown) => String(err instanceof Error ? err.message : err).replace(/^(Hooks)?Error: /, '').slice(0, 300)

function store($: EngineInterface): Store {
  return { get: key => $.store.get(key), set: (key, value) => $.store.set(key, value) }
}

function folderDeps($: EngineInterface): FolderDeps {
  return { list: p => $.fs.list(p), read: async p => String(await $.fs.read(p)), bytes: async p => (await $.fs.read(p, { as: 'bytes' })).base64, exists: p => $.fs.exists(p) }
}

/** Every game from a folder: the plugin's own (shipped, a snapshot of the
 *  gallery), then the person's (~/.drip/games); read again each time. */
async function folderGames($: EngineInterface): Promise<{ games: FolderGame[]; skipped: string }> {
  const d = folderDeps($)
  const shipped = await loadGames(d, `${$.plugin.root}/games`, TAKEN, () => !settings.sounds, false)
  const home = await $.env.get('HOME')
  if (!home) return { games: shipped.games, skipped: '' }
  const yours = await loadGames(d, gamesDir(home), new Set([...TAKEN, ...shipped.games.map(g => g.name)]), () => !settings.sounds, true)
  return { games: [...shipped.games, ...yours.games], skipped: skippedText('~/.drip/games', yours.skipped) }
}

/** Every drip from a folder, for the card: the plugin's own, then the person's. */
async function folderDrips($: EngineInterface): Promise<{ name: string; title: string; icon: string | null; isYours: boolean; author: string }[]> {
  const d = folderDeps($)
  const builtIn = new Set(Object.keys(ONE_SHOT_EFFECTS))
  const shipped = (await loadDrips(d, `${$.plugin.root}/drips`, builtIn, false)).drips
  const home = await $.env.get('HOME')
  const yours = home ? (await loadDrips(d, dripsDir(home), new Set([...builtIn, ...shipped.map(x => x.name)]), true)).drips : []
  return [...shipped, ...yours].map(x => ({ name: x.name, title: x.title, icon: x.icon, isYours: x.isYours, author: x.author }))
}

/** /drip share <name>: one of the person's own, to the gallery as a pull request. */
async function shareToGallery($: EngineInterface, name: string): Promise<string> {
  const home = await $.env.get('HOME')
  if (!home) return 'No home folder to share from.'
  return galleryShare(
    {
      run: async (argv, opts) => {
        const r = await $.process.run(argv, opts).catch(() => null)
        return r ? { exitCode: r.exitCode, stdout: String(r.stdout ?? ''), stderr: String(r.stderr ?? '') } : null
      },
      exists: p => $.fs.exists(p),
      read: async p => String(await $.fs.read(p)),
      bytes: async p => (await $.fs.read(p, { as: 'bytes' })).base64,
      now: () => $.clock.now(),
    },
    home,
    name,
  )
}

/** /drip get <name>: the gallery's game or drip, into the person's folder. */
async function getFromGallery($: EngineInterface, name: string): Promise<string> {
  const home = await $.env.get('HOME')
  if (!home) return 'No home folder to keep it in.'
  // Getting one already fetched fetches it again: the gallery's newest.
  const have = new Set([...TAKEN, ...Object.keys(ONE_SHOT_EFFECTS)])
  const said = await galleryGet(
    {
      fetch: url => $.http.fetch(url),
      write: (path, text) => $.fs.write(path, text),
      writeBytes: async (path, base64) => (await $.process.run(['/usr/bin/base64', '-D', '-o', path], { stdin: base64 }).catch(() => null))?.exitCode === 0,
    },
    home,
    name,
    have,
  )
  rowsKept = null // here now: the pane reads it afresh
  return said
}

/** A game by any of its names: built in, else the person's own. */
async function findGame($: EngineInterface, name: string): Promise<Game | null> {
  return gameOf(name) ?? (await folderGames($)).games.find(g => g.name === name.trim().toLowerCase()) ?? null
}

function overlayDeps($: EngineInterface): OverlayDeps {
  return {
    run: (argv, opts) => $.process.run(argv, opts).catch(() => null),
    spawn: (argv, input) => eventsOf($.process.spawn({ argv, input })),
    read: async path => String(await $.fs.read(path)),
    exists: path => $.fs.exists(path),
    home: () => $.env.get('HOME'),
    root: $.plugin.root,
  }
}

/** The window Claude runs in: the desktop app's, or the terminal's that hosts this session. */
async function findTarget($: EngineInterface, binary: string): Promise<Target | null> {
  const env: TerminalEnv = {
    TERM_PROGRAM: await $.env.get('TERM_PROGRAM'),
    __CFBundleIdentifier: await $.env.get('__CFBundleIdentifier'),
    TERM: await $.env.get('TERM'),
  }
  const isDesktop = (await $.session.surfaces()).includes('desktop')
  return selectTarget({ isDesktop, env, ancestors: await ancestorsOf(overlayDeps($), binary) })
}

function placement($: EngineInterface, binary: string): Placement {
  if (settings.display === 'fullscreen') return { kind: 'fullscreen' }
  return {
    kind: 'window',
    target: () => (target ??= findTarget($, binary)),
    missed: () => {
      if (!isMissedSaid) $.ui.toast("Games could not find Claude's window: games play over the screen under the pointer.")
      isMissedSaid = true
    },
  }
}

/** The list /drip answers with: each game, its other names and your best. */
async function listing($: EngineInterface): Promise<string> {
  const scores = scoresOf(store($))
  const lines = ['Games. /drip <game> starts one:']
  const yours = await folderGames($)
  for (const g of [...GAMES, ...yours.games]) {
    const best = await scores.best(g.name)
    const mine = 'isYours' in g && g.isYours ? '  ·  yours' : ''
    lines.push(`  ${g.name.padEnd(9)} ${g.title}${best > 0 ? `  ·  best ${best}` : ''}${mine}`)
  }
  if (yours.skipped) lines.push('', yours.skipped)
  return lines.join('\n')
}

/** /drip's own words, never a name to look for in the gallery. */
const WORDS = ['list', 'stop', 'save', 'delete', 'page', 'get', 'share']

/** Whether `name` plays as a drip here: built in, a folder of one, or a saved recipe. */
async function isDripHere($: EngineInterface, name: string): Promise<boolean> {
  if (name in ONE_SHOT_EFFECTS || BUILTIN_EFFECT_LIST.some(d => d.name === name)) return true
  if ((await folderDrips($)).some(d => d.name === name)) return true
  return name in (await readCustoms(store($)))
}

/** What the gallery has, for a name not on this Mac and the pane; null offline. */
async function gallery($: EngineInterface) {
  const now = await $.clock.now()
  if (galleryKept && now - galleryKept.at < GALLERY_MS) return galleryKept.index
  const index = await galleryListing({ fetch: url => $.http.fetch(url) })
  galleryKept = { at: now, index }
  return index
}

/** Who made it, as the pane says it: Drip's own are "Drip built". */
export const byOf = (author: string) => (author === DRIP_AUTHOR ? 'Drip built' : `@${author}`)

/** One row of the pane's table. */
export type Row = {
  kind: Kind
  name: string
  title: string
  about: string
  emoji: string
  by: string | null
  best: number
  isYours: boolean
  isGallery: boolean
}

/** Every game and drip for the pane: here first (games, then drips), then the gallery's not fetched yet. */
async function paneRows($: EngineInterface): Promise<Row[]> {
  const scores = scoresOf(store($))
  const rows: Row[] = []
  for (const g of [...GAMES, ...(await folderGames($)).games]) {
    const f = 'isYours' in g ? (g as FolderGame) : null
    rows.push({
      kind: 'game',
      name: g.name,
      title: g.title,
      about: f?.about ?? BUILT_IN[g.name]?.about ?? '',
      emoji: emojiOf('game', g.name, f?.emoji),
      by: byOf(f ? f.author : DRIP_AUTHOR),
      best: await scores.best(g.name),
      isYours: f?.isYours === true,
      isGallery: false,
    })
  }
  const own = await folderDrips($)
  const saved = await readCustoms(store($))
  const drip = (d: { name: string; title: string; about?: string; emoji?: string; by: string | null; isYours: boolean }): Row => ({
    kind: 'drip',
    name: d.name,
    title: d.title,
    about: d.about ?? BUILT_IN[d.name]?.about ?? '',
    emoji: emojiOf('drip', d.name, d.emoji),
    by: d.by,
    best: 0,
    isYours: d.isYours,
    isGallery: false,
  })
  rows.push(
    ...BUILTIN_EFFECT_LIST.map(d => drip({ name: d.name, title: titleOf(d.name), by: byOf(DRIP_AUTHOR), isYours: false })),
    ...own.map(d => drip({ ...d, by: byOf(d.author) })),
    // A saved recipe is the person's, made of built-in drips: its recipe is its line.
    ...Object.entries(saved)
      .filter(([n]) => !own.some(d => d.name === n))
      .map(([name, recipe]) => drip({ name, title: titleOf(name), about: recipe, by: null, isYours: true })),
  )
  const index = await gallery($)
  const here = new Set(rows.map(r => r.name))
  const fromGallery = (kind: Kind, e: Entry): Row => ({
    kind,
    name: e.name,
    title: e.title,
    about: e.about ?? '',
    emoji: emojiOf(kind, e.name, e.emoji),
    by: e.author ? byOf(e.author) : null,
    best: 0,
    isYours: false,
    isGallery: true,
  })
  for (const e of index?.games ?? []) if (!here.has(e.name)) rows.push(fromGallery('game', e))
  for (const e of index?.drips ?? []) if (!here.has(e.name)) rows.push(fromGallery('drip', e))
  return rows
}

/** Rows to a page of the pane's table. */
export const PAGE_ROWS = 15

/** The rows a search (every word, in the name, line, type, maker or "yours") and a filter leave, in order. */
export function shown(rows: readonly Row[], query: string, filter: Kind | 'all'): Row[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  return rows.filter(r => {
    if (filter !== 'all' && r.kind !== filter) return false
    const text = `${r.title} ${r.name} ${r.about} ${TYPES[r.kind]} ${r.by ?? ''} ${r.isYours ? 'yours' : ''}`.toLowerCase()
    return words.every(w => text.includes(w))
  })
}

/** A favourite's key, as the tray and the store keep it. */
export const favKey = (kind: Kind, name: string) => `${kind}:${name}`

/** The largest picture the pane can draw: an Svg's source is at most 131072 characters. */
const SVG_MAX = 131_072

/** The pane's rows as last read, kept until a /drip command or a fetch changes what's here: a press redraws at once. */
let rowsKept: Row[] | null = null

/** The pane's rows: kept ones, else read afresh. */
async function rowsOf($: EngineInterface): Promise<Row[]> {
  rowsKept ??= await paneRows($)
  return rowsKept
}

/** Each page's screenshot as the pane draws it, by "kind:name": loading while it is read, null for none. */
const shots = new Map<string, string | null | 'loading'>()

/** The gallery's covers fetched this load, base64 by "kind:name": one fetch each. */
const galleryCovers = new Map<string, string | null>()

/** An item's screenshot as base64 JPEG or PNG ({ type, base64 }), from wherever it lives; null without one. */
async function coverOf($: EngineInterface, r: Row): Promise<{ type: string; base64: string } | null> {
  const read64 = async (path: string) => ((await $.fs.exists(path).catch(() => false)) ? (await $.fs.read(path, { as: 'bytes' })).base64 : null)
  const home = await $.env.get('HOME')
  if (!r.isGallery) {
    // A folder's (fetched or the person's), else a built-in one's in the plugin's covers/.
    for (const file of COVER_FILES) {
      const b = home ? await read64(`${home}/.drip/${r.kind}s/${r.name}/${file}`) : null
      if (b) return { type: file.endsWith('.png') ? 'png' : 'jpeg', base64: b }
    }
    const b = await read64(`${$.plugin.root}/covers/${r.kind}-${r.name}.jpg`)
    return b ? { type: 'jpeg', base64: b } : null
  }
  const key = favKey(r.kind, r.name)
  if (!galleryCovers.has(key)) {
    const index = await gallery($)
    const entry = (r.kind === 'game' ? index?.games : index?.drips)?.find(e => e.name === r.name)
    const file = COVER_FILES.find(f => entry?.files.includes(f))
    const res = file ? await $.http.fetch(`${GALLERY_API}/${r.kind}s/${r.name}/${file}?ref=main`).catch(() => null) : null
    let base64: string | null = null
    try {
      const v = res?.ok ? (JSON.parse(res.text) as { encoding?: string; content?: string }) : null
      base64 = v?.encoding === 'base64' && typeof v.content === 'string' ? v.content.replace(/\s+/g, '') : null
    } catch {
      base64 = null
    }
    galleryCovers.set(key, base64 && file ? `${file.endsWith('.png') ? 'png' : 'jpeg'}:${base64}` : null)
  }
  const kept = galleryCovers.get(key)
  return kept ? { type: kept.slice(0, kept.indexOf(':')), base64: kept.slice(kept.indexOf(':') + 1) } : null
}

/** A screenshot as an Svg the pane can draw (480×300, filled); null when there is none or it is too big. */
export function screenshotSvg(cover: { type: string; base64: string } | null): string | null {
  if (!cover) return null
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="480" height="300" viewBox="0 0 480 300"><image width="480" height="300" preserveAspectRatio="xMidYMid slice" href="data:image/${cover.type};base64,${cover.base64}"/></svg>`
  return svg.length <= SVG_MAX ? svg : null
}

/** The pane's search: the rows it leaves, from the first page. */
async function search($: EngineInterface, text: string): Promise<void> {
  await update($, query, () => text)
  await update($, page, () => 0)
}

/** Stars or unstars an item: the tray above the prompt shows the starred ones. */
async function toggleFavourite($: EngineInterface, key: string): Promise<void> {
  const next = await update($, favourites, list => (list.includes(key) ? list.filter(k => k !== key) : [...list, key]))
  await $.store.set(FAVOURITES_KEY, next)
}

/** Play or Install on the pane (or the tray): plays it, or installs the gallery's
 *  (its row then says Play). */
async function press($: EngineInterface, row: Row): Promise<void> {
  if (row.isGallery) {
    const got = await getFromGallery($, row.name).catch(err => `/drip: ${short(err)}`)
    await update($, shotTick, n => n + 1)
    $.ui.toast(got.startsWith('Got ') ? `${row.title} is installed.` : got)
    return
  }
  const said = row.kind === 'drip'
      ? await queueDrip($, row.name).then(() => 'Got')
      : await play($, (await findGame($, row.name))!).catch(err => `/drip: ${short(err)}`)
  if (!said.startsWith('Got') && !said.includes('Esc quits')) $.ui.toast(said)
}

/** A drip for the drips' half (../drips) to play. */
async function queueDrip($: EngineInterface, name: string): Promise<void> {
  const at = await $.clock.now()
  await update($, queued, () => ({ recipe: name, at }))
}

/** Fetches the gallery's `name` (/drip <name>), then plays it:
 *  says what happened when it couldn't. */
async function getThenPlay($: EngineInterface, kind: Kind, name: string): Promise<string> {
  const got = await getFromGallery($, name)
  if (!got.startsWith('Got ')) return got
  if (kind === 'drip') {
    await queueDrip($, name)
    return got
  }
  const game = await findGame($, name)
  return game ? play($, game) : got
}

/** Starts `game` in the overlay; resolves once it is on screen. The score it
 *  posts is kept when it beats the top one. */
async function play($: EngineInterface, game: Game): Promise<string> {
  // One game at a time (drips may stack; games don't).
  if (gameOpen) return `${gameOpen} is already open. Quit it with Esc first.`
  gameOpen = game.title
  try {
    return await playOne($, game)
  } catch (err) {
    gameOpen = null
    throw err
  }
}

async function playOne($: EngineInterface, game: Game): Promise<string> {
  native ??= prepareOverlay(overlayDeps($))
  const prepared = await native
  if (!('binary' in prepared)) {
    gameOpen = null
    return prepared.missing
  }
  const scores = scoresOf(store($))
  const best = await scores.best(game.name)
  const { show } = overlayHost(overlayDeps($), prepared.binary, placement($, prepared.binary))
  const shown = await show(
    s => gameDoc(game, s.w, s.h, best, settings.sounds),
    async ev => void (ev.t === 'score' && (await scores.keep(game.name, ev.score))),
  )
  void shown.closed.catch(() => undefined).finally(() => (gameOpen = null))
  return `${game.title}${best > 0 ? `: your best is ${best}` : ''}. Esc quits, M mutes.`
}

export function arcade(on: On, options: PluginOptions) {
  settings = settingsOf(options)
  native = null
  gameOpen = null
  target = null
  isMissedSaid = false
  galleryKept = null
  galleryCovers.clear()
  shots.clear()
  rowsKept = null

  // The Drip pane (/drip, /drip list): a search, a filter by type, and a
  // table, fifteen rows a page: emoji, name, line, type, ☆ (the tray) and Play
  // (Install for the gallery's).
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, ...els } = $.ui.resolve(e)
    const Input = 'Input' in els ? els.Input : null
    // Every surface but the terminal draws SVG: the logo; the terminal gets the word.
    const Svg = e.surface !== 'terminal' && 'Svg' in els ? els.Svg : null
    await read($, shotTick) // an install redraws the rows
    const all = await rowsOf($)
    const q = await read($, query)
    const f = await read($, filter)
    const rows = shown(all, q, f)
    const pages = Math.max(1, Math.ceil(rows.length / PAGE_ROWS))
    const at = Math.min(await read($, page), pages - 1)
    const stars = await read($, favourites)
    // One item's page: ← back to its type, its screenshot, its line and its button.
    const opened = await read($, detail)
    const item = opened ? all.find(r => favKey(r.kind, r.name) === opened) : undefined
    if (item) {
      const key = favKey(item.kind, item.name)
      // The page draws now; its screenshot follows once read (a gallery one is fetched).
      await read($, shotTick)
      if (Svg && !shots.has(key)) {
        shots.set(key, 'loading')
        void coverOf($, item)
          .then(c => shots.set(key, screenshotSvg(c)))
          .catch(() => shots.set(key, null))
          .then(() => update($, shotTick, n => n + 1))
      }
      const shot = shots.get(key) ?? null
      const isStar = stars.includes(key)
      return (
        <Box flexDirection="column" gap={1} paddingX={1}>
          <Box key="top" flexDirection="row">
            <Button key="back" label={`←\u00a0\u00a0${TYPES[item.kind]}s`} plain onPress={() => void update($, detail, () => null)} />
          </Box>
          {shot === 'loading' ? (
            <Text key="shot" dimColor>
              Loading screenshot…
            </Text>
          ) : shot && Svg ? (
            <Svg key="shot" source={shot} alt={`${item.title}, playing`} width={480} height={300} />
          ) : (
            <Text key="shot">{item.emoji}</Text>
          )}
          <Box key="name" flexDirection="row" alignItems="center" gap={1}>
            <Text>{item.emoji}</Text>
            <Text bold>{item.title}</Text>
            {item.by ? <Text dimColor>{item.by}</Text> : null}
            {item.isYours ? <Text dimColor>yours</Text> : null}
          </Box>
          {item.about ? <Text key="about">{item.about}</Text> : null}
          <Text key="type" dimColor>
            {TYPES[item.kind]}
            {item.best > 0 ? ` · Best ${item.best.toLocaleString('en-GB')}` : ''}
          </Text>
          <Box key="act" flexDirection="row" alignItems="center" gap={1}>
            <Button key={`${item.isGallery ? 'get' : 'play'}:${key}`} label={item.isGallery ? 'Install' : 'Play'} variant="primary" onPress={() => void press($, item)} />
            <Button key={`fav:${key}`} label={isStar ? '★' : '☆'} plain dimColor={!isStar} onPress={() => void toggleFavourite($, key)} />
          </Box>
        </Box>
      )
    }
    const kinds = (Object.keys(TYPES) as Kind[]).filter(k => all.some(r => r.kind === k))
    const turn = (by: number) => () => void update($, page, p => Math.max(0, Math.min(pages - 1, Math.min(p, pages - 1) + by)))
    return (
      <Box flexDirection="column" gap={1} paddingX={1}>
        <Box key="logo" flexDirection="row" alignItems="center" gap={1}>
          {Svg ? (
            <Svg key="logo" source={LOGO} alt={LOGO_ALT} height={28} width={Math.round(28 * LOGO_RATIO)} />
          ) : (
            <Text bold>drip</Text>
          )}
        </Box>
        {Input ? (
          <Input
            key="search"
            placeholder="Search games and drips"
            value={q}
            submitLabel="search"
            onInput={value => void search($, value)}
            onSubmit={value => void search($, value)}
          />
        ) : null}
        <Box flexDirection="row" gap={1}>
          {(['all', ...kinds] as const).map(k => (
            <Button
              key={`filter:${k}`}
              label={k === 'all' ? `All ${all.length}` : `${TYPES[k]}s ${all.filter(r => r.kind === k).length}`}
              plain
              dimColor={f !== k}
              onPress={() => void update($, filter, () => k).then(() => update($, page, () => 0))}
            />
          ))}
        </Box>
        <Box flexDirection="column" gap={1}>
          {rows.length === 0 ? <Text dimColor>Nothing matches “{q}”.</Text> : null}
          {rows.slice(at * PAGE_ROWS, (at + 1) * PAGE_ROWS).map(r => {
            const key = favKey(r.kind, r.name)
            const isStar = stars.includes(key)
            return (
              <Box key={key} flexDirection="row" alignItems="center" gap={2}>
                {/* The name button keeps its own room: nothing beside it is laid over it. */}
                <Box flexShrink={0}>
                  <Button key={`open:${key}`} label={`${r.emoji}\u00a0\u00a0\u00a0${r.title}`} plain onPress={() => void update($, detail, () => key)} />
                </Box>
                {r.isYours ? <Text dimColor>yours</Text> : null}
                <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
                  <Text dimColor wrap="truncate">{r.about || r.by || ''}</Text>
                </Box>
                <Box flexShrink={0}>
                  <Text dimColor>{TYPES[r.kind]}</Text>
                </Box>
                <Button key={`fav:${key}`} label={isStar ? '★' : '☆'} plain dimColor={!isStar} onPress={() => void toggleFavourite($, key)} />
                <Button
                  key={`${r.isGallery ? 'get' : 'play'}:${key}`}
                  label={r.isGallery ? 'Install' : 'Play'}
                  variant="secondary"
                  onPress={() => void press($, r)}
                />
              </Box>
            )
          })}
        </Box>
        {pages > 1 ? (
          <Box flexDirection="row" alignItems="center" gap={1}>
            <Button key="prev" label="‹" plain dimColor={at === 0} onPress={turn(-1)} />
            <Text dimColor>
              {at + 1} of {pages}
            </Text>
            <Button key="next" label="›" plain dimColor={at === pages - 1} onPress={turn(1)} />
          </Box>
        ) : null}
      </Box>
    )
  })

  // The tray above the prompt: the drips' half (../drips) draws the starred
  // drips and its own buttons; the starred games go in front, played here.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const band = await next(e)
    if (e.props.hasSurvey || !(await read($, bandOpen))) return band
    const games = (await read($, favourites)).filter(k => k.startsWith('game:')).map(k => k.slice(5))
    if (games.length === 0) return band
    const { Box, Button } = $.ui.resolve(e)
    const all = await rowsOf($)
    const tray = games.map(n => all.find(r => r.kind === 'game' && r.name === n)).filter((r): r is Row => r !== undefined)
    return (
      <Box flexDirection="row" flexWrap="wrap" gap={1}>
        {tray.map(r => (
          <Button key={`tray:game:${r.name}`} label={`${r.emoji} ${r.title}`} onPress={() => void press($, r)} />
        ))}
        {band}
      </Box>
    )
  })

  // /drip <game> starts a game; /drip alone lists the games, then the drips
  // (the drips' half, ../drips); anything else is the drips' to play.
  on('command.run', { command: 'drip' }, async ($, e, next) => {
    rowsKept = null // a /drip command may change what's here: the pane reads it afresh
    const name = e.args.trim()
    const [verb, ...rest] = name.split(/\s+/)
    if (verb?.toLowerCase() === 'get') return { text: rest.length === 1 ? await getFromGallery($, rest[0]!) : 'Usage: /drip get <name>' }
    if (verb?.toLowerCase() === 'share') return { text: rest.length === 1 ? await shareToGallery($, rest[0]!) : 'Usage: /drip share <name>' }
    if (!name || name.toLowerCase() === 'list') {
      // The pane; where no surface places one (a bare terminal), the list in words.
      const { isPlaced } = await $.ui.open({ id: PANE, title: 'Drip', focus: true })
      if (isPlaced) return { text: OPENED }
      const drips = await next({ ...e, args: 'list' })
      return { text: `${await listing($)}\n\n${drips.text ?? ''}`.trim() }
    }
    const game = await findGame($, name)
    if (!game) {
      // Not here: the gallery's, fetched and played.
      const want = name.toLowerCase()
      if (!NAME.test(want) || WORDS.includes(want) || (await isDripHere($, want))) return next(e)
      const index = await gallery($)
      const kind = index?.games.some(g => g.name === want) ? 'game' : index?.drips.some(d => d.name === want) ? 'drip' : null
      if (!kind) return next(e)
      return { text: await getThenPlay($, kind, want).catch(err => `/drip: ${short(err)}`) }
    }
    try {
      return { text: await play($, game) }
    } catch (err) {
      return { text: `/drip: ${short(err)}` }
    }
  })
}

files.hooks/drips/hooks.tsx:
// Drips, wired to the engine: the one file of this module that holds `$` and
// the mod's state (the engine follows `$` and atoms only within the file
// whose hook received them), handing the rest closures. It runs the Drips
// page's helper (helper/server.mjs), detached so it outlives the mod's
// reloads, and the native overlay (native/overlay.swift), one process per
// effect, over Claude's window or the whole screen. Where effects play is the
// /config row `display`. The Drips button sits in the hint line under the
// prompt; pressed, a row of quick plays opens above the prompt.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On, PluginOptions, RenderChildren, Timer } from 'claude-code'

import type { HelperInfo } from '../../types'
import { BUILTIN_EFFECT_LIST, BUILTIN_EFFECTS, ONE_SHOT_EFFECTS, setYourDrips, yourDrips } from './effects.ts'
import { dripsDir, loadDrips } from '../content/folders.ts'
import { moveOnce } from '../content/moved.ts'
import { createFun } from './fun.ts'
import { emojiOf } from '../arcade/catalog.ts'
import { FAVOURITES_KEY, favouritesOf } from '../arcade/favourites.ts'
import { deleteCustom, dripId, listCustoms, readCustoms, saveCustom, type Store } from './library.ts'
import { HELPER_FILES, linkTo, versionOf, type Link, type PageMessage } from './link.ts'
import { createManager, customEffects, type Host, type Manager } from './manager.ts'
import { ancestorsOf, eventsOf, prepareOverlay, type Placement, type Prepared } from '../overlay/host.ts'
import { selectTarget, type Target, type TerminalEnv } from '../overlay/target.ts'
import { nativeHost, type NativeDeps } from './native.ts'
import { findNode, NODE_MISSING } from './node.ts'
import { settingsOf, type Settings } from './settings.ts'
import { showPage, shownText, type PageDeps } from './window.ts'

const helperInfo = atom({ plugin: 'drip', key: 'helper' } as const, null as HelperInfo | null)
const pageTab = atom({ plugin: 'drip', key: 'pageTab' } as const, null as string | null)
const nodePath = atom({ plugin: 'drip', key: 'node' } as const, null as string | null)
const bandOpen = atom({ plugin: 'drip', key: 'bandOpen' } as const, false)
/** The starred items, the tray's buttons (the pane stars them; kept in the store). */
const favourites = atom({ plugin: 'drip', key: 'favourites' } as const, [] as string[])
/** A drip the card asked to play (../arcade queues it): taken within a beat. */
const queued = atom({ plugin: 'drip', key: 'queued' } as const, null as { recipe: string; at: number } | null)
/** How often the drips' half looks for a drip the card queued, in ms. */
export const QUEUE_MS = 150


const TOOL_PREFIX = 'mcp__drip__'
const NOT_A_RECIPE = ['save', 'delete', 'list']

/** This load's pieces: made at the session's start (a reload makes them again). */
type Mod = {
  manager: Manager
  /** The native overlay's binary, built on first use. */
  native: Promise<Prepared> | null
  /** The window Claude runs in, found on first use. */
  target: Promise<Target | null> | null
  fun: ReturnType<typeof createFun>
}
let settings: Settings
let mod: Mod | null = null
/** The helper this load talks to, and the timer that collects the page's messages. */
let helper: Link | null = null
let collecting: Timer | null = null
let starting: Promise<Link> | null = null
/** Each is said once per load: the overlay unavailable, Claude's window not found. */
let isUnavailableSaid = false
let isMissedSaid = false

/** The overlay cannot run here: said once by a toast, never again by report. */
class Unavailable extends Error {}

const short = (err: unknown) => String(err instanceof Error ? err.message : err).replace(/^(Hooks)?Error: /, '').slice(0, 300)

/** What Drip before 2.0.0 kept, brought over once (../content/moved.ts). */
async function moveFromBefore($: EngineInterface): Promise<void> {
  const home = await $.env.get('HOME')
  if (!home) return
  const config = (await $.env.get('CLAUDE_CONFIG_DIR')) || `${home}/.claude`
  const moved = await moveOnce(
    {
      list: p => $.fs.list(p),
      read: async p => String(await $.fs.read(p)),
      exists: p => $.fs.exists(p),
      run: async argv => (await $.process.run(argv).catch(() => null))?.exitCode ?? null,
    },
    store($),
    { home, config },
  )
  if (moved && moved.folders.length) $.ui.toast(`Drip brought over your ${moved.folders.length === 1 ? 'game or drip' : `${moved.folders.length} games and drips`} into ~/.drip`)
}

function store($: EngineInterface): Store {
  return { get: key => $.store.get(key), set: (key, value) => $.store.set(key, value) }
}

function pageDeps($: EngineInterface): PageDeps {
  return {
    isDesktop: async () => (await $.session.surfaces()).includes('desktop'),
    mcp: (server, tool, args) => $.mcp.call(server, tool, args),
    openExternal: async url => (await $.process.run(['open', url]).catch(() => null))?.exitCode === 0,
    // A prompt submitted from inside a command would wait on the command
    // itself: it goes once the command has returned.
    ask: text =>
      void $.clock.after(0, () => {
        $.prompt.submit({ text }).catch(() => $.ui.toast('The Browser pane is not available: allow mcp__Claude_Browser__preview_start'))
      }),
    link: () => startHelper($),
    tab: { get: () => read($, pageTab), set: async fn => void (await update($, pageTab, fn)) },
  }
}

/** `quiet`: the overlay plays no sound whatever the setting (the matrix while
 *  tools run, which would otherwise sound through every long run). */
function nativeDeps($: EngineInterface, quiet = false): NativeDeps {
  return {
    run: (argv, opts) => $.process.run(argv, opts).catch(() => null),
    spawn: (argv, input) => eventsOf($.process.spawn({ argv, input })),
    read: async path => String(await $.fs.read(path)),
    exists: path => $.fs.exists(path),
    home: () => $.env.get('HOME'),
    root: $.plugin.root,
    sounds: () => !quiet && settings.sounds,
  }
}

function build($: EngineInterface): Mod {
  const report = (err: unknown) => void (err instanceof Unavailable || $.ui.toast(`Drips: ${short(err)}`))
  const manager = createManager({
    store: store($),
    customs: () => readCustoms(store($)),
    after: (ms, fn) => void $.clock.after(ms, fn),
    report,
    changed: () => $.ui.invalidate('ui.render'), // the row's Stop comes and goes
  })
  const m: Mod = { manager, native: null, target: null, fun: null as never }
  m.fun = createFun(
    {
      play: async recipe => void (await manager.execute(() => hostOf($, m), recipe)),
      ensure: async effect => manager.ensure(await hostOf($, m, true), effect),
      release: effect => manager.release(effect),
      after: (ms, fn) => $.clock.after(ms, fn),
      report,
    },
    settings,
  )
  return m
}

const modOf = ($: EngineInterface) => (mod ??= build($))

/** The window Claude runs in: the desktop app's, or the terminal's that
 *  hosts this session (its ancestors, as the overlay sees them, and the
 *  environment). */
async function findTarget($: EngineInterface, binary: string): Promise<Target | null> {
  const env: TerminalEnv = {
    TERM_PROGRAM: await $.env.get('TERM_PROGRAM'),
    __CFBundleIdentifier: await $.env.get('__CFBundleIdentifier'),
    TERM: await $.env.get('TERM'),
  }
  const isDesktop = (await $.session.surfaces()).includes('desktop')
  return selectTarget({ isDesktop, env, ancestors: await ancestorsOf(nativeDeps($), binary) })
}

function placement($: EngineInterface, m: Mod, binary: string, display: 'claude-window' | 'fullscreen'): Placement {
  if (display === 'fullscreen') return { kind: 'fullscreen' }
  return {
    kind: 'window',
    target: () => (m.target ??= findTarget($, binary)),
    missed: () => {
      if (!isMissedSaid) $.ui.toast("Drips could not find Claude's window: effects play over the screen under the pointer.")
      isMissedSaid = true
    },
  }
}

/** Where effects play now: the setting's host, the native overlay. Where the
 *  overlay cannot run here (not a Mac, no Command Line Tools), nothing plays:
 *  a toast says why, once, and the play answers with the same reason. */
async function hostOf($: EngineInterface, m: Mod, quiet = false): Promise<Host> {
  const display = settings.display
  m.native ??= prepareOverlay(nativeDeps($))
  const prepared = await m.native
  if ('binary' in prepared) return nativeHost(nativeDeps($, quiet), prepared.binary, placement($, m, prepared.binary, display))
  if (!isUnavailableSaid) $.ui.toast(prepared.missing)
  isUnavailableSaid = true
  throw new Unavailable(prepared.missing)
}

/** The engine's own line with the Drips button after it; pressed, it opens or closes the row above the prompt. */
async function withButton($: EngineInterface, e: Parameters<EngineInterface['ui']['resolve']>[0], line: RenderChildren) {
  const { Box, Button } = $.ui.resolve(e)
  const isOpen = await read($, bandOpen)
  return (
    <Box flexDirection="row" gap={2}>
      {line}
      <Button key="drip" label="💧 drip" plain dimColor={!isOpen} onPress={() => update($, bandOpen, v => !v)} />
    </Box>
  )
}

// ── The Drips page's helper ─────────────────────────────────────────────────

const linkOf = ($: EngineInterface, info: HelperInfo) => linkTo((url, init) => $.http.fetch(url, init), info.port, info.token)

async function helperVersion($: EngineInterface): Promise<string> {
  const texts = []
  for (const f of HELPER_FILES) texts.push(String(await $.fs.read(`${$.plugin.root}/helper/${f}`).catch(() => '')))
  return versionOf(texts)
}

/** The page's saved recipes and effects, sent to the helper. */
async function pushLibrary($: EngineInterface): Promise<void> {
  $.ui.invalidate('ui.render') // the row above the prompt lists them too
  await helper?.library({ drips: await listCustoms(store($)), effects: BUILTIN_EFFECTS, display: settings.display })
}

/** What the page asked: a preview played, everything stopped, a recipe saved or deleted. */
async function onPage($: EngineInterface, m: PageMessage): Promise<void> {
  const { manager } = modOf($)
  if (m.t === 'stop') return manager.stopAll()
  if (m.t === 'play') {
    await manager.execute(() => hostOf($, modOf($)), m.recipe, { preview: true })
    return
  }
  if (m.t === 'save') {
    if (!dripId(m.name) || customEffects(m.recipe).length === 0) return $.ui.toast('Drips: a drip needs a name and at least one effect.')
    if (m.original && dripId(m.original) !== dripId(m.name)) await deleteCustom(store($), m.original)
    await saveCustom(store($), m.name, m.recipe)
  } else await deleteCustom(store($), m.name)
  await pushLibrary($)
}

/** Talks to a running helper: the page's messages collected every second,
 *  which keeps it alive; one that stopped answering is let go. */
async function attach($: EngineInterface, link: Link): Promise<Link> {
  helper = link
  collecting?.cancel()
  collecting = $.clock.every(1000, () => {
    link
      .inbox()
      .then(async messages => {
        for (const m of messages) await onPage($, m).catch(err => void (err instanceof Unavailable || $.ui.toast(`Drips: ${short(err)}`)))
      })
      .catch(async () => {
        if (helper !== link) return
        collecting?.cancel()
        helper = null
        await update($, helperInfo, () => null)
      })
  })
  await pushLibrary($)
  return link
}

/** The helper kept from before this load: found again when its code is this
 *  copy's; told to leave when it is not. */
async function reattach($: EngineInterface, version: string): Promise<Link | null> {
  const kept = await read($, helperInfo)
  if (!kept) return null
  const link = linkOf($, kept)
  const running = await link.state().then(s => s.version, () => null)
  if (running === version) return attach($, link)
  if (running !== null) await link.quit().catch(() => undefined)
  collecting?.cancel()
  helper = null
  await update($, helperInfo, () => null)
  return null
}

const randomHex = (n: number) => Array.from(crypto.getRandomValues(new Uint8Array(n)), b => b.toString(16).padStart(2, '0')).join('')

/** The page's helper: the one running, or a new one started detached on a
 *  port and with a token chosen here; up when it answers. */
function startHelper($: EngineInterface): Promise<Link> {
  if (helper) return Promise.resolve(helper)
  starting ??= (async () => {
    const version = await helperVersion($)
    const kept = await reattach($, version)
    if (kept) return kept
    const node = await read($, nodePath)
    if (!node) throw new Error(NODE_MISSING)
    for (let attempt = 0; attempt < 2; attempt++) {
      const info: HelperInfo = { port: 20000 + (crypto.getRandomValues(new Uint16Array(1))[0]! % 40000), token: randomHex(24) }
      const launch = $.process.spawn({
        argv: [node, `${$.plugin.root}/helper/server.mjs`],
        env: { DRIPS_DETACH: '1', DRIPS_PORT: String(info.port), DRIPS_TOKEN: info.token, DRIPS_VERSION: version },
      })
      for await (const _ of launch); // the launcher starts the helper in its own session and exits
      const link = linkOf($, info)
      for (let i = 0; i < 20; i++) {
        if ((await link.state().then(s => s.version, () => null)) === version) {
          await update($, helperInfo, () => info)
          return attach($, link)
        }
        await $.clock.sleep(100)
      }
    }
    throw new Error('the Drips page did not start')
  })().finally(() => {
    starting = null
  })
  return starting
}

// ── The Drips button and its row ────────────────────────────────────────────

/** A play from the row or the card: the same path as /drip. */
async function bandPlay($: EngineInterface, recipe: string): Promise<void> {
  await readYours($).catch(() => undefined)
  const m = modOf($)
  await m.manager.execute(() => hostOf($, m), recipe).catch(err => void (err instanceof Unavailable || $.ui.toast(`Drips: ${short(err)}`)))
}


/** Reads the folder drips again (the plugin's shipped ones, then ~/.drip/drips): before each play and listing. */
async function readYours($: EngineInterface): Promise<void> {
  const d = {
    list: (p: string) => $.fs.list(p),
    read: async (p: string) => String(await $.fs.read(p)),
    bytes: async (p: string) => (await $.fs.read(p, { as: 'bytes' })).base64,
    exists: (p: string) => $.fs.exists(p),
  }
  const builtIn = new Set(Object.keys(ONE_SHOT_EFFECTS))
  const shipped = (await loadDrips(d, `${$.plugin.root}/drips`, builtIn, false)).drips
  const home = await $.env.get('HOME')
  const yours = home ? (await loadDrips(d, dripsDir(home), new Set([...builtIn, ...shipped.map(x => x.name)]), true)).drips : []
  setYourDrips([...shipped, ...yours], !settings.sounds)
}

/** Plays the drip the card queued, if any: the same path as a quick play. */
async function takeQueued($: EngineInterface): Promise<void> {
  const q = await read($, queued)
  if (!q) return
  await update($, queued, () => null)
  await bandPlay($, q.recipe)
}

// ── Hooks ───────────────────────────────────────────────────────────────────

async function registerAll($: EngineInterface): Promise<void> {
  await $.command.register({
    name: 'drip',
    description: 'Drip: /drip list opens the pane of games and drips; /drip snake starts a game; /drip confetti, /drip 3 hearts stars, /drip -1 aurora play drips; get <name> fetches a game or drip from the gallery, share <name> sends one of yours there; stop, save <name> <recipe>, delete <name>; page opens your saved drips and the editor. Every game and drip is free',
    argumentHint: '<game> | <recipe> | get <name> | share <name> | stop | save <name> <recipe> | delete <name> | page',
    immediate: true,
  })
  await $.tool.register({
    name: 'play_drip',
    description:
      'Play a visual effect over Claude for the person: a recipe such as "confetti", "3 hearts stars", "0.6 fireworks", ' +
      '"-1 aurora" (persistent: plays until fired again or "stop"), a saved drip\'s name, or "stop". list_drips lists the effects.',
    inputSchema: { type: 'object', properties: { recipe: { type: 'string', description: 'The drip recipe' } }, required: ['recipe'] },
  })
  await $.tool.register({
    name: 'list_drips',
    description: "List the visual effects play_drip can play, and the person's saved drips.",
    inputSchema: { type: 'object', properties: {} },
  })
}

export function drips(on: On, options: PluginOptions) {
  settings = settingsOf(options)
  mod = null
  helper = null
  isUnavailableSaid = false
  isMissedSaid = false

  on('session.start', async ($, e, next) => {
    mod = build($)
    await moveFromBefore($).catch(() => null)
    const kept = favouritesOf(await $.store.get(FAVOURITES_KEY))
    await update($, favourites, () => kept)
    await update($, nodePath, () => null)
    const node = await findNode({ run: argv => $.process.run(argv).catch(() => null) })
    await update($, nodePath, () => node)
    await reattach($, await helperVersion($)).catch(() => null) // a reload keeps the page up
    await registerAll($)
    $.clock.every(QUEUE_MS, () => void takeQueued($).catch(err => $.ui.toast(`drip ✗ ${short(err)}`)))
    return next(e)
  })

  on('command.run', { command: 'drip' }, async ($, e) => {
    // What the games' half (../arcade) passes on: `list` (or nothing) lists, anything else is a recipe or a name to play.
    const line = e.args.trim() || 'list'
    const sub = line.split(/\s+/)[0]?.toLowerCase() ?? ''
    if (sub === 'page') {
      if (!(await read($, nodePath))) return { text: NODE_MISSING }
      return { text: await showPage(pageDeps($)).then(shownText, err => `The Drip page ✗ ${short(err)}`) }
    }
    try {
      await readYours($).catch(() => undefined)
      const m = modOf($)
      const text = await m.manager.execute(() => hostOf($, m), line)
      if (sub === 'save' || sub === 'delete') await pushLibrary($).catch(() => undefined)
      return { text }
    } catch (err) {
      return { text: `/drip: ${short(err)}` }
    }
  })

  on('tool.call', { tool: 'mcp__drip__play_drip' }, async ($, e) => {
    const recipe = String((e.input as { recipe?: unknown } | undefined)?.recipe ?? '').trim()
    if (NOT_A_RECIPE.includes(recipe.split(/\s+/)[0]?.toLowerCase() ?? '')) return { result: 'play_drip takes a recipe or "stop"; list_drips lists the effects.' }
    try {
      await readYours($).catch(() => undefined)
      const m = modOf($)
      return { result: String(await m.manager.execute(() => hostOf($, m), recipe)) }
    } catch (err) {
      return { result: `Not played: ${short(err)}` }
    }
  })

  on('tool.call', { tool: 'mcp__drip__list_drips' }, async ($, e) => {
    await readYours($).catch(() => undefined)
    const own = yourDrips().map(d => ({ name: d.name, kind: d.kind, title: d.title }))
    return { result: JSON.stringify({ effects: BUILTIN_EFFECT_LIST, yours: own, custom: await listCustoms(store($)), running: modOf($).manager.running() }) }
  })

  // The Drips button, beside the engine's own line: on the terminal the hint
  // under the prompt; on the desktop, which draws no hint line of the engine's,
  // the mode labels in the prompt's footer.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const line = await next(e)
    if (!settings.button || e.surface === 'desktop') return line
    return withButton($, e, line)
  })
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const line = await next(e)
    if (!settings.button || e.surface !== 'desktop') return line
    return withButton($, e, line)
  })

  // Its row above the prompt, the tray: the starred drips (the games' half,
  // ../arcade, puts the starred games in front), Stop while something
  // persistent plays, ✕.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!settings.button || e.props.hasSurvey || !(await read($, bandOpen))) return next(e)
    const { Box, Button } = $.ui.resolve(e)
    const close = <Button key="close" label="✕" plain role="dismiss" onPress={() => update($, bandOpen, () => false)} />
    const saved = new Set((await listCustoms(store($))).map(d => d.name))
    await readYours($).catch(() => undefined)
    const own = yourDrips()
    // A starred drip that plays here: built in, a folder of one, or a saved recipe.
    const starred = (await read($, favourites))
      .filter(k => k.startsWith('drip:'))
      .map(k => k.slice(5))
      .filter(n => BUILTIN_EFFECTS.includes(n) || saved.has(n) || own.some(d => d.name === n))
    const isPlaying = modOf($).manager.running().length > 0
    return (
      <Box flexDirection="row" flexWrap="wrap" gap={1}>
        {starred.map(n => {
          const d = own.find(x => x.name === n)
          return <Button key={`play:${n}`} label={`${emojiOf('drip', n, d?.emoji)} ${d?.title ?? n}`} onPress={() => bandPlay($, n)} />
        })}
        {isPlaying ? [<Button key="stop" label="■ Stop" onPress={() => modOf($).manager.stopAll()} />] : []}
        {close}
      </Box>
    )
  })

  // The fun hooks: each does nothing unless its /config toggle is on.
  on('tool.call', async ($, e, next) => {
    if (!settings.matrixWhileTools || e.agentId || String(e.tool).startsWith(TOOL_PREFIX)) return next(e)
    const { fun } = modOf($)
    void fun.toolStart()
    try {
      return await next(e)
    } finally {
      fun.toolEnd()
    }
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    void modOf($)
      .fun.turnEnd({ durationMs: e.durationMs, reason: e.reason, isMainLoop: !e.agentId })
      .catch(err => void (err instanceof Unavailable || $.ui.toast(`Drips: ${short(err)}`)))
    return next(e)
  })
}

