// The rules a game or drip folder must pass (the repository's README), as pure
// functions over what was read from it. Plain JavaScript, so the plugin and
// the skills' checker (skills/*/check.js, run with Node before Claude says a
// game or drip is done) apply the very same rules.

/** A folder's name: lowercase letters, digits and hyphens. */
export const NAME = /^[a-z0-9][a-z0-9-]{0,31}$/
export const TITLE_MAX = 32
export const ABOUT_MAX = 60
/** A page's most, in characters. */
export const PAGE_MAX = 512 * 1024
export const ICON_MAX = 16 * 1024
/** A cover's most, in bytes, and its sizes: 16:10, 480×300 to 1920×1200. */
export const COVER_MAX = 300 * 1024
export const COVER_MIN_W = 480
export const COVER_MAX_W = 1920
/** A GitHub login: letters, digits and single hyphens, at most 39. */
export const AUTHOR = /^[A-Za-z0-9](?:[A-Za-z0-9]|-(?=[A-Za-z0-9])){0,38}$/
/** The author Drip's own carry, which the pane shows as "Drip built". */
export const DRIP_AUTHOR = 'drip'
/** The cover files a folder may have, in the order they are looked for. */
export const COVER_FILES = ['cover.jpg', 'cover.png']

/** What reaches the network: none of it may appear in a page. */
const NETWORK = [
  /\bfetch\s*\(/,
  /\bXMLHttpRequest\b/,
  /\bWebSocket\b/,
  /\bEventSource\b/,
  /\bsendBeacon\b/,
  /\bimport\s*\(/,
  /\b(?:src|href|action)\s*=\s*["']?\s*(?:https?:)?\/\//i,
  /url\(\s*["']?\s*(?:https?:)?\/\//i,
  /@import\b/i,
]

/**
 * @typedef {{ file: string, base64: string }} Cover
 *   cover.jpg or cover.png as read: its name and its bytes, standard base64.
 * @typedef {{ name: string, manifest: string | null, page: string | null, icon: string | null, cover: Cover | null }} Read
 *   A folder as read: its name, game.json or drip.json, game.html or drip.html, icon.svg and its cover (null when absent).
 * @typedef {{ title: string, author: string, about?: string, emoji?: string }} GameManifest
 * @typedef {{ title: string, author: string, kind: 'one-shot' | 'loop', about?: string, emoji?: string }} DripManifest
 */

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Standard base64 to bytes; null when it isn't base64. @param {string} text @returns {Uint8Array | null} */
function bytesOf(text) {
  const t = text.replace(/\s+/g, '').replace(/=+$/, '')
  if (/[^A-Za-z0-9+/]/.test(t) || t.length % 4 === 1) return null
  const out = new Uint8Array(Math.floor((t.length * 3) / 4))
  let at = 0
  for (let i = 0; i < t.length; i += 4) {
    const n = [0, 1, 2, 3].map(k => (i + k < t.length ? B64.indexOf(t[i + k]) : 0))
    const v = (n[0] << 18) | (n[1] << 12) | (n[2] << 6) | n[3]
    for (const [k, shift] of [[1, 16], [2, 8], [3, 0]]) if (i + k < t.length) out[at++] = (v >> shift) & 255
  }
  return out
}

/**
 * A cover's kind and size in pixels, read from its header; null when it is
 * neither a PNG nor a JPEG it can read.
 * @param {Uint8Array} b @returns {{ type: 'png' | 'jpeg', w: number, h: number } | null}
 */
export function imageSize(b) {
  if (b.length > 24 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) {
    const w = ((b[16] << 24) | (b[17] << 16) | (b[18] << 8) | b[19]) >>> 0
    const h = ((b[20] << 24) | (b[21] << 16) | (b[22] << 8) | b[23]) >>> 0
    return { type: 'png', w, h }
  }
  if (b.length > 4 && b[0] === 0xff && b[1] === 0xd8) {
    let i = 2
    while (i + 9 < b.length) {
      if (b[i] !== 0xff) return null
      const marker = b[i + 1]
      if (marker === 0xff) {
        i++
        continue
      }
      const len = (b[i + 2] << 8) | b[i + 3]
      // A start of frame (SOF0–SOF15, not DHT, JPG or DAC) holds the size.
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return { type: 'jpeg', h: (b[i + 5] << 8) | b[i + 6], w: (b[i + 7] << 8) | b[i + 8] }
      }
      i += 2 + len
    }
  }
  return null
}

/** Why a cover won't do, or null. @param {Cover | null} c @returns {string | null} */
function coverWhy(c) {
  if (c === null) return 'it has no cover.jpg or cover.png (its picture)'
  const b = bytesOf(c.base64)
  if (b === null) return `${c.file} could not be read`
  if (b.length > COVER_MAX) return `${c.file} is over 300 KB`
  const size = imageSize(b)
  if (!size || size.type !== (c.file === 'cover.png' ? 'png' : 'jpeg')) return `${c.file} is not a ${c.file === 'cover.png' ? 'PNG' : 'JPEG'}`
  if (size.w < COVER_MIN_W || size.w > COVER_MAX_W) return `${c.file} is ${size.w}×${size.h}: it must be 480 to 1920 wide (960×600 is right)`
  if (Math.abs(size.w / size.h - 1.6) > 0.02) return `${c.file} is ${size.w}×${size.h}: it must be 16:10 (960×600 is right)`
  return null
}

/** An emoji: one short run of non-ASCII characters (an emoji with its joiners and selectors). */
export const EMOJI = /^[^\x00-\x7F]{1,12}$/

/** Why the optional about and emoji won't do, or null; else what they add to the manifest.
 * @param {Record<string, unknown>} m @param {string} file @returns {{ why: string } | { extra: { about?: string, emoji?: string } }} */
function extras(m, file) {
  if (m.about !== undefined && (typeof m.about !== 'string' || m.about.length > ABOUT_MAX)) return { why: `${file}.json's about must be text of at most ${ABOUT_MAX} characters` }
  if (m.emoji !== undefined && (typeof m.emoji !== 'string' || !EMOJI.test(m.emoji.trim()))) return { why: `${file}.json's emoji must be one emoji` }
  return {
    extra: {
      ...(typeof m.about === 'string' && m.about.trim() ? { about: m.about.trim() } : {}),
      ...(typeof m.emoji === 'string' ? { emoji: m.emoji.trim() } : {}),
    },
  }
}

/** Why an author won't do, or null. @param {Record<string, unknown>} m @param {string} file @returns {string | null} */
function authorWhy(m, file) {
  if (typeof m.author !== 'string' || !m.author.trim()) return `${file}.json has no author (the maker's GitHub login)`
  if (!AUTHOR.test(m.author.trim())) return `${file}.json's author must be a GitHub login`
  return null
}

/** @param {Read} r @param {string} file @returns {string | null} */
function common(r, file) {
  if (!NAME.test(r.name)) return `its folder name "${r.name}" must be lowercase letters, digits and hyphens`
  if (r.manifest === null) return `it has no ${file}.json`
  if (r.page === null) return `it has no ${file}.html`
  if (r.page.length > PAGE_MAX) return `${file}.html is over 512 KB`
  if (NETWORK.some(re => re.test(r.page))) return `${file}.html reaches the network, which isn't allowed`
  if (r.icon !== null) {
    if (r.icon.length > ICON_MAX) return 'icon.svg is over 16 KB'
    if (!/^\s*(<\?xml[^>]*>\s*)?<svg[\s>]/i.test(r.icon)) return 'icon.svg is not an SVG'
    if (/<script|\bon[a-z]+\s*=|(?:href|src)\s*=\s*["']?\s*(?:https?:)?\/\//i.test(r.icon)) return 'icon.svg has scripts or links'
  }
  return coverWhy(r.cover)
}

/** @param {string} text @returns {Record<string, unknown> | null} */
function parsed(text) {
  try {
    const v = JSON.parse(text)
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null
  } catch {
    return null
  }
}

/** @param {Record<string, unknown>} m @param {string} file @returns {string | null} */
function titled(m, file) {
  if (typeof m.title !== 'string' || !m.title.trim()) return `${file}.json has no title`
  if (m.title.trim().length > TITLE_MAX) return `${file}.json's title is over ${TITLE_MAX} characters`
  return null
}

/** @param {Read} r @returns {{ ok: true, manifest: GameManifest, page: string, icon: string | null, cover: Cover } | { ok: false, why: string }} */
export function checkGame(r) {
  const why = common(r, 'game')
  if (why) return { ok: false, why }
  const m = parsed(/** @type {string} */ (r.manifest))
  if (!m) return { ok: false, why: 'game.json is not a JSON object' }
  const t = titled(m, 'game') ?? authorWhy(m, 'game')
  if (t) return { ok: false, why: t }
  const x = extras(m, 'game')
  if ('why' in x) return { ok: false, why: x.why }
  const manifest = { title: String(m.title).trim(), author: String(m.author).trim(), ...x.extra }
  return { ok: true, manifest, page: r.page, icon: r.icon, cover: /** @type {Cover} */ (r.cover) }
}

/** @param {Read} r @returns {{ ok: true, manifest: DripManifest, page: string, icon: string | null, cover: Cover } | { ok: false, why: string }} */
export function checkDrip(r) {
  const why = common(r, 'drip')
  if (why) return { ok: false, why }
  const m = parsed(/** @type {string} */ (r.manifest))
  if (!m) return { ok: false, why: 'drip.json is not a JSON object' }
  const t = titled(m, 'drip') ?? authorWhy(m, 'drip')
  if (t) return { ok: false, why: t }
  if (m.kind !== 'one-shot' && m.kind !== 'loop') return { ok: false, why: 'drip.json\'s kind must be "one-shot" or "loop"' }
  const x = extras(m, 'drip')
  if ('why' in x) return { ok: false, why: x.why }
  return { ok: true, manifest: { title: String(m.title).trim(), author: String(m.author).trim(), kind: m.kind, ...x.extra }, page: /** @type {string} */ (r.page), icon: r.icon, cover: /** @type {Cover} */ (r.cover) }
}

files.hooks/content/share.ts:
// /drip share <name>: one of the person's own games or drips, sent to the
// gallery (timmetim/drip) as a pull request, all from the plugin. It runs
// the GitHub command-line tool, signed in as the person: their fork of the
// gallery, synced; a branch; the folder's files; the pull request. We review
// and merge it there; from then on anyone can /drip get it.
import { COVER_FILES, DRIP_AUTHOR, checkDrip, checkGame, type Cover } from './rules.js'

/** The gallery's repository on GitHub. */
export const REPO = 'timmetim/drip'

export type Run = (argv: string[], opts?: { stdin?: string; timeoutMs?: number }) => Promise<{ exitCode: number; stdout: string; stderr: string } | null>

export type ShareDeps = {
  run: Run
  exists: (path: string) => Promise<boolean>
  read: (path: string) => Promise<string>
  /** A file's bytes, standard base64 (the cover). */
  bytes: (path: string) => Promise<string>
  now: () => Promise<number>
}

/** What it says when the GitHub tool isn't there or isn't signed in. */
export const NEEDS_GH = 'Sharing needs the GitHub command-line tool, signed in: brew install gh, then gh auth login.'

const FILES = { game: ['game.json', 'game.html', 'icon.svg'], drip: ['drip.json', 'drip.html', 'icon.svg'] } as const

/** `gh` as the plugin finds it: on PATH, else where Homebrew puts it. */
async function ghPath(d: ShareDeps): Promise<string | null> {
  for (const gh of ['gh', '/opt/homebrew/bin/gh', '/usr/local/bin/gh']) {
    const r = await d.run([gh, '--version'])
    if (r?.exitCode === 0) return gh
  }
  return null
}

const say = (r: { stderr: string; stdout: string } | null) => (r ? (r.stderr || r.stdout).trim().split('\n')[0] ?? '' : 'it did not run')

/** Shares `name` from `home`'s folders; says what came of it, the pull request's link when it worked. */
export async function share(d: ShareDeps, home: string, name: string): Promise<string> {
  const want = name.trim().toLowerCase()
  const kind = (await d.exists(`${home}/.drip/games/${want}/game.json`)) ? 'game' : (await d.exists(`${home}/.drip/drips/${want}/drip.json`)) ? 'drip' : null
  if (!kind) return `No game or drip of yours called "${want}" (they live in ~/.drip/games and ~/.drip/drips).`
  const dir = `${home}/.drip/${kind}s/${want}`
  const files = new Map<string, string>()
  for (const f of FILES[kind]) if (await d.exists(`${dir}/${f}`)) files.set(f, await d.read(`${dir}/${f}`))
  let cover: Cover | null = null
  for (const f of COVER_FILES) if (!cover && (await d.exists(`${dir}/${f}`))) cover = { file: f, base64: await d.bytes(`${dir}/${f}`) }
  const read = { name: want, manifest: files.get(`${kind}.json`) ?? null, page: files.get(`${kind}.html`) ?? null, icon: files.get('icon.svg') ?? null, cover }
  const checked = kind === 'game' ? checkGame(read) : checkDrip(read)
  if (!checked.ok) return `${want} doesn't pass the check (${checked.why}), so it wasn't shared.`
  if (checked.manifest.author === DRIP_AUTHOR) return `${want}'s author is "${DRIP_AUTHOR}", which is Drip's own: put your GitHub login in ${kind}.json.`

  const gh = await ghPath(d)
  if (!gh) return NEEDS_GH
  if ((await d.run([gh, 'auth', 'status']))?.exitCode !== 0) return NEEDS_GH
  const who = await d.run([gh, 'api', 'user', '--jq', '.login'])
  const user = who?.exitCode === 0 ? who.stdout.trim() : ''
  if (!user) return `GitHub didn't say who you are: ${say(who)}`
  if (checked.manifest.author.toLowerCase() !== user.toLowerCase()) return `${want}'s author is "${checked.manifest.author}", but you're signed in to GitHub as ${user}: only its maker shares it.`

  // Their fork, created if new and brought up to date with the gallery.
  const fork = `${user}/drip`
  await d.run([gh, 'repo', 'fork', REPO, '--clone=false'], { timeoutMs: 60_000 })
  const synced = await d.run([gh, 'repo', 'sync', fork, '--source', REPO, '--branch', 'main'], { timeoutMs: 60_000 })
  if (synced?.exitCode !== 0) return `Couldn't bring your fork ${fork} up to date: ${say(synced)}`
  const head = await d.run([gh, 'api', `repos/${fork}/git/ref/heads/main`, '--jq', '.object.sha'])
  if (head?.exitCode !== 0 || !head.stdout.trim()) return `Couldn't read your fork ${fork}: ${say(head)}`

  const branch = `${kind}-${want}-${await d.now()}`
  const made = await d.run([gh, 'api', `repos/${fork}/git/refs`, '--input', '-'], { stdin: JSON.stringify({ ref: `refs/heads/${branch}`, sha: head.stdout.trim() }) })
  if (made?.exitCode !== 0) return `Couldn't make a branch on ${fork}: ${say(made)}`

  const sends: [string, string][] = []
  for (const [file, text] of files) {
    const b64 = await d.run(['/usr/bin/base64'], { stdin: text })
    if (b64?.exitCode !== 0) return `Couldn't prepare ${file}: ${say(b64)}`
    sends.push([file, b64.stdout])
  }
  sends.push([checked.cover.file, checked.cover.base64])
  for (const [file, base64] of sends) {
    const path = `${kind}s/${want}/${file}`
    const sha = await d.run([gh, 'api', `repos/${fork}/contents/${path}?ref=${branch}`, '--jq', '.sha'])
    const body = { message: `${checked.manifest.title}: ${file}`, branch, content: base64.replace(/\s+/g, ''), ...(sha?.exitCode === 0 && sha.stdout.trim() ? { sha: sha.stdout.trim() } : {}) }
    const put = await d.run([gh, 'api', '-X', 'PUT', `repos/${fork}/contents/${path}`, '--input', '-'], { stdin: JSON.stringify(body), timeoutMs: 60_000 })
    if (put?.exitCode !== 0) return `Couldn't add ${file} to ${fork}: ${say(put)}`
  }

  const what = kind === 'game' ? 'Game' : 'Drip'
  const pr = await d.run(
    [gh, 'pr', 'create', '-R', REPO, '--head', `${user}:${branch}`, '--base', 'main', '--title', `${what}: ${checked.manifest.title}`, '--body', `${what} \`${want}\`, shared from Drip with /drip share.`],
    { timeoutMs: 60_000 },
  )
  if (pr?.exitCode !== 0) return `Couldn't open the pull request: ${say(pr)}`
  const link = pr.stdout.trim().split('\n').pop() ?? ''
  return `Shared ${checked.manifest.title}: ${link}. Once it's merged, anyone can /drip get ${want}.`
}

