    dv += `<div style="position:absolute;top:${y}px;left:${startX}px;font-size:48px;filter:drop-shadow(0 0 10px rgba(255,255,255,0.7));animation:${n} ${dur}s linear ${delay}ms forwards;opacity:0">🕊️</div>`;
